export default {'swine-clinic--swine-asf':[['swine-clinic--swine-asf--รายการหัวข้อ-asf-และ-csf-ที่ออกข้อเขียน','รายการหัวข้อ ASF และ CSF ที่ออกข้อเขียน','รายการหัวข้อ asf และ csf ที่ออกข้อเขียน \n ข้อจำกัดของการตรวจ elisa ในโรค esf \n ข้อจำกัดของการตรวจ pcr ในโรค asf \n การก่อโรคแบบ late-onset csf \n เหตุผลที่ไม่นิยมตรวจ ab elisa ในโรค csf \n chronic asf มีต้นกำเนิดมาจากอะไร \n การเก็บตัวอย่างให้ได้ ปริมาณเชื้อ asf มากที่สุด ควรเก็บจากอะไร \n หน้านี้ไม่มีคำตอบอยู่เลยแม้แต่ข้อเดียว คำเฉลยของคำถาม mcq ที่สร้างจากหัวข้อเหล่านี้มาจากตำราสุกรมาตรฐาน ไม่ได้มาจากเอกสารฉบับนี้ ให้ทวนกับเลกเชอร์ปีปัจจุบันก่อนยึดเป็นคำตอบ \n เอกสารเขียนหัวข้อไว้ว่า 12 ข้อ แต่รายการที่ไล่จริงมี 13 ข้อ บันทึกไว้ตามที่เห็น ไม่ได้แก้ตัวเลขให้ และ esf กับ csf ปรากฏเป็นสองตัวย่อในเอกสารเดียวกันโดยไม่ได้อธิบายว่าหมายถึงโรคเดียวกันหรือไม่']],'swine-clinic--swine-cns':[['swine-clinic--swine-cns--ขอบเขตที่เอกสารตอบ','ขอบเขตที่เอกสารตอบ','ขอบเขตที่เอกสารตอบ \n porcine hemagglutinating encephalomyelitis virus (phev) เป็น betacoronavirus ที่ทำให้เกิด vomiting and wasting disease และหรือ encephalomyelitis และเป็นโคโรนาไวรัสตัวเดียวเท่าที่ทราบที่มีคุณสมบัติ neurotropic ในสุกร โรคทางคลินิกมักพบเฉพาะลูกสุกรอายุต่ำกว่า 4 สัปดาห์ และปัจจุบันยังไม่มีวัคซีน จึงสมเหตุสมผลที่จะจัดเป็นหนึ่งในโรคระบบประสาทของสุกร'],['swine-clinic--swine-cns--rabies-ในสุกร','Rabies ในสุกร','rabies ในสุกร \n สาเหตุ lyssavirus \n สุกรมักติดจาก การถูกสุนัขกัด เชื้อเข้าสู่ปลายประสาทแล้วเข้าไปทำลาย cns \n แนวทางจัดการคือ ทำลายสุกรที่แสดงอาการ หรือพิจารณาให้ anti-rabies serum ซึ่งราคาสูง \n ป้องกันด้วย biosecurity โดยเฉพาะการไม่ให้สุนัขหรือสัตว์อื่นเข้ามาสัมผัสสุกร \n พิจารณาวัคซีนเฉพาะในสุกรที่เลี้ยงเป็นสัตว์เลี้ยง \n rabies เป็นโรคติดต่อสู่คนและเป็นโรคที่ต้องแจ้ง การจัดการจริงต้องทำตามระเบียบของกรมปศุสัตว์ เอกสารนี้บันทึกไว้ในระดับตอบข้อสอบเท่านั้น \n ไวรัสโรคพิษสุนัขบ้าอยู่ในสกุล lyssavirus ซึ่งเป็นกลุ่มไวรัสที่ก่อ encephalitis ตรงกับที่เอกสารระบุสาเหตุไว้ \n เชื้ออยู่ในน้ำลายและสมองของสัตว์ติดเชื้อ โดยสุนัขเป็นแหล่งที่พบบ่อยที่สุด และแพร่โดยการกัด สนับสนุนที่เอกสารบอกว่าสุกรมักติดจากการถูกสุนัขกัด \n เมื่อสัตว์แสดงอาการแล้วโรคนี้ตายทุกราย จึงไม่มีการรักษาที่ได้ผล สอดคล้องกับแนวทางของเอกสารที่ให้ทำลายสัตว์ที่แสดงอาการ และการควบคุมโรคที่ได้ผลที่สุดคือการฉีดวัคซีนในสุนัข'],['swine-clinic--swine-cns--porcine-hemagglutinating-encephalomyelitis-phev','Porcine hemagglutinating encephalomyelitis (PHEV)','porcine hemagglutinating encephalomyelitis (phev) \n สาเหตุ beta coronavirus \n พบได้ 2 กลุ่มอาการ คือ encephalomyelitis ที่มีอาการทางประสาทร่วมกับอาเจียน และ vomiting and wasting disease ที่มีอาเจียน เบื่ออาหาร ซึม และแคระแกร็น \n ทั้งสองกลุ่มพบใน ลูกสุกรอายุน้อยกว่า 4 สัปดาห์ \n ไม่มีการรักษาจำเพาะ \n ป้องกันโดยสร้างภูมิให้แม่สุกรก่อนคลอดแล้วส่งต่อทาง colostrum ทั้งการทำ planned exposure และ autogenous vaccine \n จัดฟาร์มให้เป็น ฝูงปิด และควบคุม biosecurity \n phev จัดอยู่ในสกุล betacoronavirus วงศ์ coronaviridae ตรงกับที่เอกสารระบุว่าเป็น beta coronavirus \n phev ก่อโรคได้สองกลุ่มอาการคือ vomiting and wasting disease (vwd) และ encephalomyelitis ตรงกับที่เอกสารแบ่งไว้ \n อาการทางคลินิก อัตราป่วยและอัตราตายของ phev ขึ้นกับอายุ และโดยทั่วไปมีรายงานเฉพาะในลูกสุกรอายุน้อยกว่า 4 สัปดาห์ ตรงกับตัวเลขที่เอกสารระบุ \n ยังไม่มีวัคซีน phev จำหน่าย การป้องกันจึงใช้การให้เชื้อหมุนเวียนในฟาร์มโดยให้สุกรสาวและแม่สุกรสาวสัมผัสเชื้อแต่เนิ่น เพื่อสร้างภูมิของแม่แล้วส่งต่อให้ลูก ตรงกับแนวทาง planned exposure และภูมิผ่านน้ำนมเหลืองที่เอกสารเขียนไว้'],['swine-clinic--swine-cns--listeriosis','Listeriosis','listeriosis \n สาเหตุแบคทีเรีย listeria monocytogenes \n สุกรมักเป็นพาหะของเชื้อ และอาจพบการแท้งในแม่สุกร \n เป็นเชื้อที่ ติดต่อสู่คนได้ ผ่านการสัมผัสหรืออาหารที่ปนเปื้อน \n การจัดการที่เอกสารบันทึกไว้เน้นการคัดทิ้งสัตว์ป่วย ล้างคอก และพักเล้า มากกว่าการรักษาด้วยยาปฏิชีวนะ \n ประโยคเรื่องแนวทางรักษาในสุกรของหน้านี้เขียนด้วยลายมือที่อ่านได้ไม่ชัดทั้งประโยค จึงสรุปเฉพาะใจความที่อ่านออกแน่ ๆ ไม่เติมรายละเอียดยาเอง \n listeria monocytogenes เป็นเชื้อที่ติดต่อทางอาหารและก่อโรคทั้งในสัตว์และคน โดยสุกรทำหน้าที่เป็นแหล่งรังโรคแบบไม่แสดงอาการ ตรงกับที่เอกสารระบุว่าสุกรมักเป็นพาหะและเป็นเชื้อติดต่อสู่คน \n การสำรวจตามสายการผลิตสุกรจากฟาร์มถึงโรงฆ่าพบ l. monocytogenes ที่ต่อมทอนซิลมากที่สุด (ร้อยละ 24) ขณะที่พบใน rectal swab และเนื้อหาในลำไส้เพียงร้อยละ 1 ยืนยันภาพการเป็นพาหะที่ระบบทางเดินหายใจส่วนต้นมากกว่าการเป็นโรค'],['swine-clinic--swine-cns--tetanus','Tetanus','tetanus \n สาเหตุแบคทีเรีย clostridium tetani ซึ่ง สร้างสปอร์อยู่ในดิน \n เข้าสู่ร่างกายสุกร ทางบาดแผล \n เชื้อสร้าง toxin ทำลายระบบประสาท ทำให้กล้ามเนื้อหดเกร็ง spasm \n รักษาด้วยยาต้านจุลชีพกลุ่ม penicillin ในสุกรที่ยังไม่แสดงอาการเกร็ง หรือให้ tetanus antitoxin \n ป้องกันด้วยการรักษาความสะอาดในหัตถการที่ทำให้เกิดบาดแผล ให้ยาต้านจุลชีพหลังผ่าตัด และสุขาภิบาลที่ดี \n clostridium tetani เป็นแบคทีเรียแกรมบวกที่ไม่ใช้ออกซิเจน สร้างสปอร์และพบได้ทั่วไปในสิ่งแวดล้อม เข้าสู่ร่างกายทางบาดแผลที่ผิวหนัง แล้วปล่อยสารพิษต่อระบบประสาทชื่อ tetanospasmin ตรงกับกลไกที่เอกสารเขียนไว้ \n เฉพาะการสร้างภูมิคุ้มกันแบบ active ด้วยวัคซีนบาดทะยักเท่านั้นที่ให้การป้องกันการเป็นพิษจากบาดทะยักได้จริง ซึ่งหนุนน้ำหนักไปที่การป้องกันมากกว่าการรักษาหลังแสดงอาการอย่างที่เอกสารเน้น']],'swine-clinic--swine-fmd':[['swine-clinic--swine-fmd--การวินิจฉัยและพิสูจน์เชื้อ-fmd','การวินิจฉัยและพิสูจน์เชื้อ FMD','การวินิจฉัยและพิสูจน์เชื้อ fmd \n ดู ประวัติการระบาด และ ประวัติวัคซีน ของสุกรในฟาร์ม \n ดูอาการและรอยโรค เช่น ขาเจ็บ ไม่กินอาหาร และ ตุ่มน้ำที่กีบ จมูก ปาก ราวนม และหัวนม \n ผ่าซากและเก็บตัวอย่างส่งห้องปฏิบัติการ โดยเก็บ tissue ของตุ่มน้ำส่งตรวจ pcr และเก็บ serum ส่งตรวจ elisa \n ddx จากโรคอื่นที่มีรอยโรคคล้ายกัน ได้แก่ vesicular stomatitis และ swine vesicular disease \n รอยโรคของ fmd คือตุ่มน้ำที่จมูก ลิ้นหรือริมฝีปาก ในช่องปาก ระหว่างนิ้วเท้า เหนือกีบ ที่หัวนม และตามจุดรับน้ำหนักของผิวหนัง ตรงกับตำแหน่งที่เอกสารให้ตรวจ \n บางกรณีแยก fmd จากโรคอื่นด้วยอาการทางคลินิกและรอยโรคมหภาคไม่ได้ ต้องส่งตรวจทางห้องปฏิบัติการ โดยเฉพาะกรณีที่เกิดจากเชื้อ vesicular stomatitis และ swine vesicular disease ตรงกับ ddx ที่เอกสารระบุ'],['swine-clinic--swine-fmd--การรักษาและการป้องกันควบคุม-fmd','การรักษาและการป้องกันควบคุม FMD','การรักษาและการป้องกันควบคุม fmd \n การรักษา \n รักษาตามอาการและรอยโรค \n ให้ยาปฏิชีวนะเพื่อ ป้องกันการติดเชื้อแทรกซ้อนทุติยภูมิ ไม่ใช่เพื่อฆ่าไวรัส \n ฉีด vaccine เชื้อตาย โดยเลือกให้ ตรงกับ serotype ที่กำลังระบาด \n การป้องกันและควบคุม \n biosecurity \n จัดการสภาพแวดล้อม \n ทำความสะอาดและฆ่าเชื้อ \n ทำวัคซีนปูพรม \n fmd มี 7 ซีโรไทป์ (a, o, c, sat1, sat2, sat3 และ asia1) และแต่ละซีโรไทป์ต้องใช้วัคซีนจำเพาะของตัวเองจึงจะสร้างภูมิให้สัตว์ได้ ตรงกับที่เอกสารสั่งให้เลือกวัคซีนตรงซีโรไทป์ที่กำลังระบาด \n ไวรัส fmd กลายพันธุ์เร็ว วัคซีนที่มีอยู่จึงอาจให้ cross-protection ไม่พอเมื่อมีสายพันธุ์หรือสายย่อยใหม่เข้ามา จึงต้องทำ vaccine matching เทียบกับเชื้อที่ระบาดจริงในพื้นที่']],'swine-clinic--swine-gi-viral':[['swine-clinic--swine-gi-viral--กรอบคำตอบข้อเขียน-ลดเชื้อ-สร้างภูมิ','กรอบคำตอบข้อเขียน: ลดเชื้อ + สร้างภูมิ','กรอบคำตอบข้อเขียน: ลดเชื้อ + สร้างภูมิ \n 1. ลดปริมาณเชื้อก่อโรค \n จัดการ pig flow ใช้ระบบ all-in-all-out และแบ่งสุกรสาวเป็น unit เพื่อให้ควบคุมโรคได้ง่าย \n biosecurity ปฏิบัติอย่างเข้มงวด เพื่อไม่ให้เชื้อจากภายนอกเข้าสู่ภายในฟาร์ม \n ใช้ยาต้านจุลชีพอย่างเหมาะสม เลือกชนิดให้ตรงกับเชื้อ ใช้ตามข้อบ่งชี้ และ rotate ยาเมื่อต้องเปลี่ยน \n ใช้น้ำเชื้อจากพ่อพันธุ์ทำผสมเทียม เพื่อลด contact ระหว่างพ่อพันธุ์กับแม่พันธุ์ \n 2. เพิ่มภูมิคุ้มโรค \n ใช้วัคซีน เลือกรูปแบบ วิธีการให้ และวางโปรแกรมวัคซีนอย่างเหมาะสม \n จัดการโรงเรือน ดูแลความสะอาด และมีระบบระบายอากาศที่ดี \n จัดการอาหารและน้ำ ให้คุณภาพดี สะอาด ปลอดจากสารพิษปนเปื้อน \n ลดความเครียด จัดการปัจจัยที่ก่อความเครียด และดูแลสวัสดิภาพสุกร \n ข้างหัวข้อเพิ่มภูมิคุ้มโรคมีตัวย่อ vvfws เขียนกำกับไว้ ตำแหน่งตรงกับ vaccine, ventilation (โรงเรือน), feed, water และ stress พอดี แต่เอกสารไม่ได้กางคำย่อนี้ไว้ จึงเป็นการอ่านเทียบลำดับหัวข้อ ไม่ใช่คำอธิบายที่เอกสารเขียนเอง \n หน้านี้มีบันทึกข้างกระดาษของรุ่นพี่ว่าอาจารย์ผู้สอนออกข้อเขียนแนวนี้ 2 ข้อ และปีนั้นไม่ได้ออกกลุ่มไวรัสระบบประสาท เป็นการคาดการณ์ของรุ่นก่อน ไม่ใช่ข้อมูลของปีนี้ ให้ยึดขอบเขตที่อาจารย์ประกาศในปีของตัวเองเป็นหลัก \n การจัดการแบบ all-in all-out ช่วยให้สุขภาพและผลผลิตของสุกรขุนดีขึ้น และระบบเลี้ยงเป็นชุด (batch production) ออกแบบมาเพื่อปรับ pig flow ตรงกับข้อแรกของกรอบลดปริมาณเชื้อในเอกสาร \n ในการศึกษาภาคสนาม 21 ฟาร์ม การทำ all-in all-out ในโรงเรือนอนุบาลสัมพันธ์กับ seroprevalence ของ mycoplasma hyopneumoniae ที่ลดลงในฝูง ซึ่งเป็นหลักฐานเชิงตัวเลขว่าการจัดการ pig flow ลดแรงกดดันของเชื้อได้จริง'],['swine-clinic--swine-gi-viral--transmissible-gastroenteritis-tge','Transmissible gastroenteritis (TGE)','transmissible gastroenteritis (tge) \n สาเหตุ alpha coronavirus \n ลูกสุกรแรกเกิดแสดงอาการท้องเสียอย่างรุนแรง อาเจียน ไม่กินอาหาร และมี อัตราการตายสูงในลูกสุกรอายุต่ำกว่า 2 สัปดาห์ \n ติดต่อทาง fecal-oral route \n ป้องกันโดยเลือกวัตถุดิบอาหารสัตว์ที่ปราศจากเชื้อปนเปื้อน และสร้างภูมิในแม่สุกร \n การสร้างภูมิในแม่ ใช้วิธีเอาอุจจาระของแม่ที่ท้องเสียผสมน้ำให้กิน หรือเอาลูกสุกรที่ท้องเสียและตายใหม่ ๆ มาปั่นให้กิน \n ฉีดวัคซีนในแม่อุ้มท้องก่อนคลอด เพื่อส่งภูมิผ่าน colostrum ให้ลูก \n วิธีให้แม่กินอุจจาระหรือซากลูกสุกรป่วยที่ปั่นแล้ว (planned exposure หรือ feedback) เป็นสิ่งที่เอกสารบันทึกไว้ตามที่เรียน ในทางปฏิบัติจริงมีข้อควรระวังเรื่องการแพร่เชื้ออื่นไปพร้อมกัน ให้ตรวจสอบกับคำบรรยายปีปัจจุบันก่อนนำไปตอบว่าเป็นวิธีที่แนะนำ \n tgev อยู่ในสกุล alphacoronavirus และอัตราการตายในลูกสุกรสูงเกือบร้อยละ 100 ตรงกับที่เอกสารระบุว่าเป็น alpha coronavirus ที่ทำให้ลูกสุกรตายสูง \n ความรุนแรงของโรคหลังติด tgev แปรผกผันกับอายุของลูกสุกรที่ติดเชื้อ ซึ่งเป็นเหตุผลเบื้องหลังที่เอกสารระบุว่าอัตราตายสูงในลูกสุกรอายุต่ำกว่า 2 สัปดาห์'],['swine-clinic--swine-gi-viral--porcine-epidemic-diarrhea-ped','Porcine epidemic diarrhea (PED)','porcine epidemic diarrhea (ped) \n สาเหตุ alpha coronavirus เช่นเดียวกับ tge \n ท้องเสียในลูกสุกรแรกเกิด และ ความรุนแรงลดลงเมื่อลูกสุกรอายุมากขึ้น \n ปัจจัยเสี่ยงที่บันทึกไว้คือปัญหาการจัดการโรงเรือนคลอด และการที่ลูกขาด passive immunity จากแม่ \n ป้องกันโดยคุมวัตถุดิบอาหารสัตว์ไม่ให้ปนเปื้อน ร่วมกับการสร้างภูมิในแม่สุกร \n ฉีดวัคซีนในแม่อุ้มท้อง ก่อนคลอด 4 และ 2 สัปดาห์ ร่วมกับการจัดการโรงเรือนคลอดที่ดี \n บรรทัดที่กล่าวถึงสัดส่วนแม่สุกรที่ต้องได้รับการสร้างภูมิและกรอบเวลาเป็นวันในหน้านี้ ลายมืออ่านได้ไม่ชัดพอที่จะยืนยันตัวเลข จึงไม่นำมาลงไว้ ให้เทียบกับสไลด์ของปีปัจจุบัน \n pedv อยู่ในสกุล alphacoronavirus วงศ์ coronaviridae และทำให้ท้องเสียเฉียบพลัน อาเจียน ขาดน้ำ และตายสูงในลูกสุกรแรกเกิด ตรงกับที่เอกสารระบุว่าเป็น alpha coronavirus เช่นเดียวกับ tge \n สุกรที่โตกว่ามีความเปราะบางต่อ pedv ต่ำกว่าลูกสุกรดูดนม โดยบทความมีหัวข้อเฉพาะเรื่องความเปราะบางที่ลดลงในสุกรอายุมากขึ้น ตรงกับที่เอกสารระบุว่าความรุนแรงลดลงเมื่ออายุมากขึ้น \n ระดับ siga จำเพาะต่อ pedv ในน้ำนมเหลืองและน้ำนมของแม่สุกรเป็นตัวชี้ขาดระดับภูมิคุ้มกันแบบรับมาของลูก จึงเป็นเหตุผลของการทำวัคซีนแม่อุ้มท้องก่อนคลอดตามที่เอกสารเขียนไว้'],['swine-clinic--swine-gi-viral--rotavirus','Rotavirus','rotavirus \n สาเหตุ rotavirus group a, b, c และ e \n ทำให้ลูกสุกร ช่วงอายุ 7 วัน และช่วงหย่านม แสดงอาการท้องเสีย \n อัตราการตายต่ำกว่า tge \n ติดต่อจากอาหารหรือสิ่งแวดล้อมที่ปนเปื้อน \n ป้องกันโดยใช้ autogenous vaccine เนื่องจากยังไม่มีวัคซีนที่จำเพาะจำหน่ายในประเทศ และเพิ่มภูมิในแม่เพื่อส่งต่อให้ลูกทาง colostrum \n โรตาไวรัสที่มีรายงานในสุกรได้แก่ species a, b, c, e และ h ซึ่งครอบคลุมทั้งสี่กลุ่มที่เอกสารระบุ แต่มี species h เพิ่มมาอีกหนึ่งกลุ่ม \n ในบรรดาโรตาไวรัสทุก species ที่พบในสุกร rva และ rvc เป็นสองกลุ่มที่พบมากที่สุด โดย rvc กำลังเป็นสาเหตุสำคัญของลำไส้อักเสบในลูกสุกรแรกเกิด \n การเพิ่มภูมิผ่านน้ำนม (lactogenic immunity) ในสุกรสาวด้วยวัคซีนและการทำ natural planned exposure เป็นวิธีเดียวในปัจจุบันที่ป้องกันการติดโรตาไวรัสในลูกสุกรได้ สอดคล้องกับแนวทาง autogenous vaccine บวกการเพิ่มภูมิแม่ที่เอกสารเขียนไว้']],'swine-clinic--swine-pcv2':[['swine-clinic--swine-pcv2--อาการและรอยโรคที่พบร่วมกันได้ทั้งสามโรค','อาการและรอยโรคที่พบร่วมกันได้ทั้งสามโรค','อาการและรอยโรคที่พบร่วมกันได้ทั้งสามโรค \n diarrhea \n lymph node บวมโต \n cyanosis \n ซึม และเบื่ออาหาร \n respiratory sign \n ไข้สูง \n ใน classical swine fever พบต่อมน้ำเหลืองโต จุดเลือดออกและ petechiae บนผิว serosa และ mucosa ของอวัยวะหลายระบบ รวมทั้งจุดเลือดออกหรือ cyanosis ที่ผิวหนังบริเวณหู ขา และท้องด้านล่าง ตรงกับ cyanosis และ lymph node บวมโตที่เอกสารจัดเป็นอาการร่วม \n การติดเชื้อ pcv2 เกี่ยวข้องกับความผิดปกติหลายระบบ ทั้งกลุ่มอาการทางเดินอาหาร ทางเดินหายใจ และระบบสืบพันธุ์ นอกเหนือจาก postweaning multisystemic wasting syndrome จึงอธิบายว่าทำไม pcv จึงมีอาการซ้อนทับกับอีกสองโรคได้ทั้งท้องเสีย ซึม และอาการทางหายใจ'],['swine-clinic--swine-pcv2--จุดที่ใช้แยกสามโรคออกจากกัน','จุดที่ใช้แยกสามโรคออกจากกัน','จุดที่ใช้แยกสามโรคออกจากกัน \n salmonella และ swine fever \n hemorrhagic lymph node \n button ulcer \n hemorrhage ที่ผิวหนัง \n turkey egg kidney \n pcv \n จุดแดงตามผิวหนัง \n reproductive failure ที่พบในแม่สุกรได้ทุก parity \n แยกด้วยพฤติกรรมการระบาดในฟาร์ม \n pcv และ swine fever เป็นโรคจาก virus จึงไม่ตอบสนองต่อยาปฏิชีวนะ และมี distribution ในฟาร์มสูง \n salmonella เป็นโรคจาก bacteria มักเกิดโรคแบบ กระจุก และมี distribution ในฟาร์มต่ำ \n ตัวย่อ abo ที่ปรากฏในเอกสารหน้านี้และหน้าเดียวกันในข้อ fmd ผู้เขียนใช้ในความหมายเดียวกับ ab คือยาปฏิชีวนะ ไม่ได้หมายถึงหมู่เลือด \n รูปแบบเรื้อรังของ classical swine fever ทำให้เกิด necrosis และ ulceration ที่ลำไส้เล็ก ลำไส้ใหญ่ และ ileocecal valve ซึ่งคือแผลที่เอกสารเรียกว่า button ulcer \n csf ให้จุดเลือดออกและ petechiae ที่ไตซึ่งเป็นภาพที่เอกสารเรียกว่า turkey egg kidney และยังพบ splenic infarction ที่ถือว่าเป็น pathognomonic ของ csf ซึ่งเอกสารไม่ได้ระบุไว้ \n pdns เป็นโรคจาก immune complex ที่มีลักษณะ fibrino-necrotizing glomerulonephritis และ systemic necrotizing vasculitis ส่วนโรคระบบสืบพันธุ์ที่สัมพันธ์กับ pcv2 พบเป็นการแท้งช่วงท้ายและลูกตายแรกคลอด ซึ่งอธิบายทั้งจุดแดงตามผิวหนังและ reproductive failure ที่เอกสารใช้แยก pcv ออกจากอีกสองโรค'],['swine-clinic--swine-pcv2--exudative-epidermitis-และ-mycoplasma-suis-ที่บันทึกไว้โดยไม่มีคำ','Exudative epidermitis และ Mycoplasma suis ที่บันทึกไว้โดยไม่มีคำตอบ','exudative epidermitis และ mycoplasma suis ที่บันทึกไว้โดยไม่มีคำตอบ \n อาการของ exudative epidermitis ในสุกรโต \n วิธีจัดการและรักษาสุกรที่ป่วยเป็น exudative epidermitis \n อาการของลูกสุกรดูดนมที่ติด mycoplasma suis \n สองโรคนี้ไม่มีหัวข้อ curriculum ที่ตรง จึงเก็บไว้ที่ pcv2 เพราะเป็น ddx กลุ่มเดียวกันในสุกรรุ่นที่ซีด แคระแกร็น หรือมีรอยโรคผิวหนัง ไม่ได้แปลว่าเป็นโรคเดียวกัน']],'swine-clinic--swine-pornchalit-set':[['swine-clinic--swine-pornchalit-set--โรคเยื่อหุ้มปอดและปอดอักเสบในสุกร-app-ทั้งชุด','โรคเยื่อหุ้มปอดและปอดอักเสบในสุกร (APP) ทั้งชุด','โรคเยื่อหุ้มปอดและปอดอักเสบในสุกร (app) ทั้งชุด \n สาเหตุ \n อาการ แบ่งตามความรุนแรง \n peracute สุกรซึม ตายใน 6 ถึง 8 ชั่วโมง ไข้สูงกว่า 104 องศาฟาเรนไฮต์ มี blood-tinged frothy exudate ออกจากปากและจมูก และ cyanosis ที่ปลายขา \n acute ตายใน 24 ถึง 48 ชั่วโมง ไข้สูงกว่า 104 องศาฟาเรนไฮต์ ซึม เบื่ออาหาร หายใจลำบาก \n chronic อาการไม่ชัดเจน หายใจด้วยท้อง และกลายเป็น พาหะนำโรค \n การวินิจฉัย \n bacterial isolation เป็น gold standard และต่อยอดทำ antimicrobial sensitivity test ได้ \n serology ได้แก่ elisa, cft, immunodiffusion, agglutination \n pcr ใช้จำแนก subtype ได้ \n การรักษา \n การควบคุมและป้องกัน \n หาสาเหตุโน้มนำที่ทำให้เกิดโรค เช่น ความหนาแน่นและการระบายอากาศที่ไม่ดี \n ปรับปรุงการจัดการฟาร์ม เช่น all-in-all-out และนำสุกรที่ปลอดโรคเข้าฟาร์ม \n คัดพาหะนำโรคที่ทำให้เกิดการระบาดออกจากฝูง \n ใช้ยาเพื่อควบคุมการแพร่กระจายของเชื้อ \n ใช้วัคซีนเพื่อสร้างภูมิคุ้มกัน โดยมุ่งไปที่ diva vaccine ที่ไม่มี apxiv เพื่อแยกสัตว์ที่ได้วัคซีนออกจาก natural infection \n ทำความสะอาดและฆ่าเชื้อโรงเรือน \n actinobacillus pleuropneumoniae เป็นแบคทีเรียแกรมลบในวงศ์ pasteurellaceae ที่ก่อโรคเยื่อหุ้มปอดและปอดอักเสบในสุกร ตรงกับที่เอกสารระบุว่าเป็นแบคทีเรียแกรมลบ \n สุกรที่เป็นโรครูปแบบ peracute และ acute มีภาวะหายใจลำบากรุนแรงและอัตราตายสูง ตรงกับการจัดกลุ่มความรุนแรงและการตายเร็วที่เอกสารบันทึกไว้ \n apxiv toxin ถูกสร้างโดย a. pleuropneumoniae เฉพาะในร่างกายสัตว์ (in vivo) จึงใช้ elisa ต่อ apxiv ตรวจการติดเชื้อและแยกสัตว์ที่ติดเชื้อออกจากสัตว์ที่ได้วัคซีนได้ ตรงกับหลักการ diva vaccine ที่ไม่มี apxiv ในเอกสาร \n วัคซีน app ที่ใช้อยู่ยังคุ้มครองไม่ครบถ้วน และมักป้องกันได้เฉพาะซีโรวาร์ที่ใช้ผลิตวัคซีนเท่านั้น ซึ่งเป็นข้อจำกัดที่เอกสารไม่ได้เขียนไว้ในหัวข้อการควบคุมป้องกัน'],['swine-clinic--swine-pornchalit-set--ปัจจัยทางการจัดการที่ทำให้คุม-app-ไม่ได้ผล','ปัจจัยทางการจัดการที่ทำให้คุม APP ไม่ได้ผล','ปัจจัยทางการจัดการที่ทำให้คุม app ไม่ได้ผล \n สุกรสาวทดแทนเป็นพาหะนำโรคเข้าฟาร์ม \n ซื้อสุกรเข้าฟาร์มจากหลายแหล่ง \n เลี้ยงด้วยระบบต่อเนื่อง ไม่พักโรงเรือน \n ความเครียด \n เลี้ยงหนาแน่นเกินไป \n สุกรเชิงพาณิชย์ส่วนใหญ่มีเชื้อ a. pleuropneumoniae อาศัยอยู่โดยไม่แสดงอาการ ซึ่งเป็นพื้นฐานของข้อที่เอกสารระบุว่าสุกรสาวทดแทนและสุกรที่ซื้อเข้าฟาร์มทำหน้าที่เป็นพาหะนำโรคเข้าฝูง \n ในการศึกษาภาคสนามในบราซิล seroprevalence ของ app สัมพันธ์กับการเกิด pleuritis ในฝูง และการทำ all-in all-out ในโรงเรือนอนุบาลลด seroprevalence ของ m. hyopneumoniae ซึ่งสนับสนุนว่าการเลี้ยงต่อเนื่องไม่พักโรงเรือนเป็นปัจจัยจัดการที่ทำให้คุมโรคทางเดินหายใจไม่ได้'],['swine-clinic--swine-pornchalit-set--รอยโรคสำคัญรายเชื้อ-ข้อ-3','รอยโรคสำคัญรายเชื้อ (ข้อ 3)','รอยโรคสำคัญรายเชื้อ (ข้อ 3) \n mycoplasma hyopneumoniae ให้ purple to gray consolidation ที่ cranioventral lung lobes และ lung atelectasis จนเนื้อปอดเป็น meaty parenchyma \n actinobacillus pleuropneumoniae ให้ hemorrhagic และ fibrinonecrotic pneumonia มีฝีหนอง ร่วมกับ fibrinous pleuritis และ serofibrinous exudate ในช่องอก \n haemophilus parasuis (glässerella parasuis) ให้ fibrinopurulent polyserositis, meningitis และ arthritis \n pneumonic pasteurellosis ให้ cranioventral lung consolidation ที่มี clear demarcation line ร่วมกับ pleuritis และฝีหนอง เยื่อหุ้มปอด translucent and dry \n atrophic rhinitis ให้ใบหน้าผิดรูปและ atrophy ของ nasal turbinate จมูกคดงอที่ nasal septum และใน par มี chronic osteolysis ที่ถูกแทนที่ด้วยพังผืด \n actinobacillus suis เป็น early colonizer พบรอยโรคได้ทุกช่วงอายุ มีจุดเลือดออกแบบ petechial และ ecchymotic ในหลายอวัยวะ ปอดมี disseminated foci ของ hemorrhagic ถึง necrotic pneumonia มี serofibrinous exudate ในช่องท้องและช่องอก polyarthritis และ vascular emboli จาก bacterial septicemia \n mycoplasma hyorhinis ให้ serofibrinous polyserositis และ arthritis \n mycoplasma hyosynoviae ให้ arthritis ร่วมกับ osteochondrosis \n streptococcus suis เป็น early colonizer ให้ septicemia, meningitis, endocarditis, pneumonia และ arthritis \n ในกระดาษเขียนคำว่า atropic rhinitis ตามที่ผู้เขียนสะกด คำที่ถูกคือ atrophic rhinitis และ pneumonia pasteurellosis ที่ถูกคือ pneumonic pasteurellosis ตอบในข้อสอบให้สะกดตามคำที่ถูก \n รายชื่อ 4 ตัวหลังเป็นสิ่งที่รุ่นพี่เติมเองเพื่อเผื่อไว้ ไม่ได้อยู่บนกระดาษข้อสอบที่พิมพ์มา ขอบเขตของปีนี้ให้ยึดที่อาจารย์ประกาศ \n รอยโรคปอดแข็งตัวบริเวณ cranioventral คือภาพของ enzootic pneumonia ส่วนรอยโรคที่เยื่อหุ้มปอดกลีบ dorsocaudal บ่งชี้ pleuropneumonia จาก actinobacillus pleuropneumoniae ตรงกับการแบ่งรอยโรครายเชื้อที่เอกสารเขียนไว้ \n glaesserella (haemophilus) parasuis เป็นสาเหตุของ glasser\'s disease ที่ทำให้เกิดการติดเชื้อทั่วร่างกายพร้อม polyserositis, meningitis และ arthritis ตรงกับรอยโรคสามอย่างที่เอกสารระบุ \n atrophic rhinitis เกิดจาก pasteurella multocida และ bordetella bronchiseptica มีลักษณะสำคัญคือการฝ่อของกระดูก nasal turbinate ซึ่งทำให้จมูกสั้นและผิดรูปในรายที่รุนแรง ตรงกับรอยโรคที่เอกสารระบุ'],['swine-clinic--swine-pornchalit-set--actinobacillus-suis-สไลด์ที่แนบไว้ท้ายเล่ม','Actinobacillus suis (สไลด์ที่แนบไว้ท้ายเล่ม)','actinobacillus suis (สไลด์ที่แนบไว้ท้ายเล่ม) \n pathogenesis \n เชื้อรุกล้ำผ่าน tonsil แล้วกระจายทางกระแสเลือด ซึ่งเห็นได้จากการพบเชื้ออยู่ใน emboli ในหลอดเลือด ที่ตำแหน่งรอยโรคหลายแห่ง \n ก่อโรคผ่านการสร้าง hemolysin และ toxin ที่คล้ายกับของ a. pleuropneumoniae (apxi, apxii) \n เชื่อว่าเป็น early colonizer ของลูกสุกรแรกเกิด \n สภาพแวดล้อมที่ไม่เหมาะสมหรือโรคร่วม ทำให้เชื้อก่อโรคได้ง่ายขึ้น \n clinical signs \n สัญญาณแรกของการระบาดคือ สุกรเล็กตายเฉียบพลัน จากภาวะ bacterial septicemia \n สุกรป่วยมีไข้ หายใจเร็ว ปลายอวัยวะคั่งเลือดหรือเขียวคล้ำ \n พบ cyanosis, arthritis, enteritis และบางครั้ง necrosis ที่เท้า หาง หู ซึ่งคล้ายกับ erysipelas และ salmonellosis \n อัตราการตายในครอกที่ได้รับผลกระทบสูงได้ถึงราว 50 เปอร์เซ็นต์ \n สุกรรุ่นและสุกรโตอาจมีอาการหายใจลำบากเฉียบพลันร่วมด้วย และ แม่สุกรอุ้มท้องอาจแท้ง \n lesions \n รอยโรคมหภาคคล้ายกัน ในทุกช่วงอายุ มีจุดเลือดออก petechial และ ecchymotic ในหลายอวัยวะ \n ปอดมี disseminated foci ของ hemorrhagic ถึง necrotizing pneumonia \n รอยโรคที่พบสม่ำเสมอคือ serous ถึง serofibrinous exudate ในช่องท้องและช่องอก และพบ polyarthritis ในสุกรรุ่นถึงขุน \n รอยโรคจุลภาคเกิดรอบ ๆ โคโลนีเล็ก ๆ ของเชื้อภายใน vascular emboli หรือ thrombi บางครั้งมี eosinophilic clubs ล้อมรอบ \n ทั้งรอยโรคมหภาคและจุลภาคเข้าได้กับ embolic bacterial septicemia \n actinobacillus suis ร่วมกับ haemophilus parasuis และ streptococcus suis เป็นเชื้อที่เข้ามาตั้งรกรากในสุกรตั้งแต่ระยะแรก (early colonizer) จึงควบคุมยากแม้ใช้วิธีจัดการอย่าง segregated early weaning และมีความสำคัญมากในฝูงสุขภาพดี ตรงกับที่สไลด์ระบุว่า a. suis เป็น early colonizer ของลูกสุกรแรกเกิด \n a. suis sensu stricto ถูกจัดเป็นเชื้อฉวยโอกาส (opportunistic pathogen) ของสุกร ซึ่งสอดคล้องกับที่สไลด์อธิบายว่าสภาพแวดล้อมที่ไม่เหมาะสมหรือโรคร่วมทำให้เชื้อก่อโรคได้ง่ายขึ้น'],['swine-clinic--swine-pornchalit-set--pneumonic-pasteurellosis-pasteurella-multocida-type-a-และ-d','Pneumonic pasteurellosis / Pasteurella multocida type A และ D','pneumonic pasteurellosis / pasteurella multocida type a และ d \n pathogenesis \n suppurative reaction จากการแทรกของนิวโทรฟิลเนื่องจาก lps \n กระตุ้น inflammatory cytokines \n ตายจาก endotoxic shock ร่วมกับภาวะหายใจล้มเหลว \n clinical signs \n acute หายใจลำบาก หายใจด้วยท้อง นอนหมดแรง ไข้สูงราว 108 องศาฟาเรนไฮต์ และตายพร้อมผิวหนังท้องเปลี่ยนเป็นสีม่วง \n subacute ไอ หายใจด้วยท้อง ผอมแห้งอย่างมาก \n chronic ไอ หายใจด้วยท้องและ thumping ไข้ต่ำจนถึงไม่มีไข้ \n lesions \n anteroventral lung consolidation ที่มีเส้นแบ่งเขตชัดเจน \n มี frothy exudate ในหลอดลม และเนื้อปอดเปลี่ยนสีจากแดงเป็นเขียวเทา \n pleuritis และ abscessation เยื่อหุ้มปอดใสและแห้ง (translucent and dry pleura) \n จุดที่ใช้แยกจาก app คือลักษณะเยื่อหุ้มปอด pneumonic pasteurellosis ให้เยื่อหุ้มปอด ใสและแห้ง ส่วน app ให้ fibrinous pleuritis และ serofibrinous exudate ในช่องอก \n pasteurella multocida ที่แยกได้จากปอดบวมในสุกรโดยทั่วไปเป็นสายพันธุ์ capsular type a ที่ไม่สร้าง toxin ขณะที่สายพันธุ์สร้าง toxin ที่สัมพันธ์กับ progressive atrophic rhinitis มักเป็น capsular type d แม้ type a ที่สร้าง toxin ก็พบได้ ซึ่งอธิบายที่มาของการเขียนว่า type a และ d ในสไลด์ \n เชื้อ p. multocida ที่แยกจากปอดบวมในสุกรได้มาจากรอยโรค bronchopneumonia ที่อยู่บริเวณ cranioventral และไอโซเลตที่เลือกมาตรวจทั้งหมดเป็น capsular serotype a ตรงกับตำแหน่งรอยโรคที่สไลด์ระบุ'],['swine-clinic--swine-pornchalit-set--atrophic-rhinitis-npar-และ-par','Atrophic rhinitis (NPAR และ PAR)','atrophic rhinitis (npar และ par) \n non-progressive atrophic rhinitis (npar) เกิดจาก toxigenic bordetella bronchiseptica \n progressive atrophic rhinitis (par) เกิดจาก toxigenic pasteurella multocida เดี่ยว ๆ หรือร่วมกับเชื้ออื่นเช่น b. bronchiseptica \n ทั้งสองแบบให้ nasal turbinate bone hypoplasia, ใบหน้าผิดรูปรวมถึง brachygnathia superior, จมูกและ septum เบี้ยวไปด้านข้าง และ nasal haemorrhage ซึ่งพบเฉพาะ par \n lesions และการประเมิน \n ประเมินโดย ตัดขวางจมูกที่ระดับฟันกรามน้อยซี่ที่ 1 ถึง 2 (premolar 1-2) \n ดู atrophy ของ ventral scroll ของ ventral turbinate และการคดของ nasal septum \n scoring of snout จาก 0 ถึง 5 \n morphometric index คือสัดส่วนช่องว่างต่อพื้นที่หน้าตัดทั้งหมด \n par: พังผืดเข้าแทนที่แผ่นกระดูกที่ ventral conchae ถือเป็น pathognomonic lesion \n clinical signs แยกตามเชื้อ \n b. bronchiseptica ให้ rhinitis คือ จาม ฟุดฟิด มีน้ำมูก serous ถึง mucopurulent และ bronchopneumonia คือ ไอ เสียง whoop หายใจลำบาก \n p. multocida ให้ acute catarrhal rhinitis คือ จาม ฟุดฟิด มีน้ำมูกและ เลือดออกจมูก ใบหน้าผิดรูปแบบ push-up appearance จากการสั้นลงของสันจมูก และมี dirty streak จากคราบน้ำตาที่ดักฝุ่น \n dermonecrotic toxin ของ p. multocida เป็นโปรตีนขนาด 146 kda ที่เข้ารหัสด้วยยีน toxa และเป็นตัวรับผิดชอบต่ออาการทางคลินิกและพยาธิกำเนิดของ progressive atrophic rhinitis ตรงกับที่สไลด์ระบุว่า par เกิดจาก toxigenic p. multocida \n toxin ของ p. multocida และ dermonecrotic toxin ของ bordetella รบกวนการสร้างกระดูก turbinate โดยยับยั้งการเปลี่ยนสภาพของ osteoblast และหรือกระตุ้นการสลายกระดูกโดย osteoclast ทั้งแบบแยกกันและร่วมกัน ซึ่งเป็นกลไกเบื้องหลังการฝ่อของ turbinate ที่สไลด์ให้ประเมินด้วย scoring และ morphometric index'],['swine-clinic--swine-pornchalit-set--mycoplasma-hyopneumoniae-enzootic-pneumonia','Mycoplasma hyopneumoniae (enzootic pneumonia)','mycoplasma hyopneumoniae (enzootic pneumonia) \n ลักษณะของเชื้อและผลกระทบ \n ความเสียหายทางเศรษฐกิจมาจากตัวโรคเอง รวมถึงการเจริญเติบโตที่ลดลง และการเสริมฤทธิ์กับเชื้ออื่นใน prdc \n เลี้ยงยาก (fastidious) และมักถูก m. hyorhinis ขึ้นกลบ ซึ่ง m. hyorhinis เป็นเชื้อประจำถิ่นในทางเดินหายใจ ส่วน m. flocculare ไม่ก่อโรคในปอดสุกร \n มีผลกับสุกรอายุ 3 ถึง 6 เดือน และทำให้การเจริญเติบโตลดลง \n pathogenesis \n ระยะฟักตัว 10 ถึง 16 วัน ในสภาพธรรมชาติ \n ทำลาย cilia ของ trachea, bronchi และ bronchioles จนเกิดการสูญเสีย cilia อย่างกว้างขวาง \n peribronchial และ perivascular lymphoreticular hyperplasia \n กระบวนการก่อโรคซับซ้อน ทั้ง attachment และ colonization, cytotoxicity, การแย่งสารอาหาร และการหลบเลี่ยงกับปรับเปลี่ยนภูมิคุ้มกันของโฮสต์ \n ยึดเกาะ cilia ของเซลล์หลอดลมด้วยโปรตีนหลายชนิด (สไลด์ระบุขนาด 97, 145, 28.5 และ 52 kda) \n เยื่อหุ้มเซลล์ของเชื้อเป็น mitogenic ต่อ porcine lymphocyte เปลี่ยนการทำงานของ alveolar macrophage และกดภูมิคุ้มกัน \n เอื้อให้เกิดปอดบวมจาก pasteurella multocida และ actinobacillus pleuropneumoniae ตามมา \n clinical signs \n ไอเรื้อรังแบบไม่มีเสมหะ (chronic non-productive cough) \n อัตราป่วยสูงแต่อัตราตายต่ำ \n ตายจากการติดเชื้อแบคทีเรียแทรกซ้อนและความเครียดที่อายุ 4 ถึง 6 เดือน โดยมีอาการเบื่ออาหาร หายใจลำบากแบบ thumping ไอมากขึ้น ไข้สูง และนอนหมดแรง \n lesions \n มหภาค purple to gray consolidation ที่ cranioventral lobes ได้แก่ apical, cardiac, accessory และ diaphragmatic \n ระยะต้นถึงกลาง มี catarrhal exudate ในทางเดินหายใจ และต่อมน้ำเหลือง bronchial กับ mediastinal โต \n ระยะเรื้อรัง ปอด atelectatic เป็น meaty แต่ไม่แข็งมากเกินไป \n จุลภาค ระยะต้นมีนิวโทรฟิลสะสมใน lamina รอบทางเดินหายใจและถุงลม ตามด้วย lymphocyte infiltration, eosinophilic exudate ในถุงลม, lymphoid hyperplasia และ mononuclear cells ในถุงลมจนผนัง alveolar septa หนาขึ้น \n รอยโรคที่หายแล้วพบ alveolar emphysema และ hyperplasia ของ lymphoid nodules \n การควบคุม \n วัคซีนแบบ two-shot ให้ผลด้าน growth performance ดีขึ้น รอยโรคที่ปอดน้อยลง มี antibody response อาการทางคลินิกดีขึ้น และ roi ดีกว่า \n ยาที่สไลด์ระบุ ได้แก่ tiamulin ร่วมกับ chlortetracycline, lincomycin ร่วมกับ ctc และกลุ่ม quinolones เช่น enrofloxacin, danofloxacin, ofloxacin, marbofloxacin \n ร่วมกับ biosecurity \n m. hyopneumoniae เป็นเชื้อตัวเริ่มต้นของ porcine respiratory disease complex และเป็นสาเหตุของ enzootic pneumonia ส่วน m. flocculare เมื่อให้เชื้อเดี่ยวในสุกร spf ไม่ทำให้เกิดอาการทางคลินิก ความเปลี่ยนแปลงทางโลหิตวิทยา หรือรอยโรคมหภาคเลย ตรงกับที่สไลด์ระบุว่า m. flocculare ไม่ก่อโรคในปอดสุกร \n การยึดเกาะของ m. hyopneumoniae ทำให้เกิด ciliostasis ตามด้วยการสูญเสีย cilia และเซลล์เยื่อบุตาย ตรงกับกลไกทำลาย cilia ของ trachea, bronchi และ bronchioles ที่สไลด์เขียนไว้ \n ยาที่มีฤทธิ์ต่อ m. hyopneumoniae ได้แก่กลุ่ม tetracyclines, macrolides, lincosamides, pleuromutilins, amphenicols, aminoglycosides, aminocyclitols และ fluoroquinolones ซึ่งครอบคลุมยาที่สไลด์ระบุ (tiamulin เป็น pleuromutilin, ctc เป็น tetracycline, lincomycin เป็น lincosamide และกลุ่ม quinolones) และเชื้อยังดื้อโดยธรรมชาติต่อ beta-lactam sulfonamides และ trimethoprim'],['swine-clinic--swine-pornchalit-set--mycoplasma-hyorhinis-และ-mycoplasma-hyosynoviae','Mycoplasma hyorhinis และ Mycoplasma hyosynoviae','mycoplasma hyorhinis และ mycoplasma hyosynoviae \n m. hyorhinis \n ก่อ polyserositis และ arthritis \n pathogenesis เริ่มจากโรคอื่นหรือความเครียด นำไปสู่ septicaemia แล้วไป colonize ที่ข้อและเยื่อบุช่องลำตัว เกิด acute serofibrinous inflammation บางสายพันธุ์ทำให้เกิดปอดบวมได้ \n อาการ ขนหยาบ ไข้ขึ้น เบื่ออาหาร ไม่อยากเคลื่อนไหว หายใจด้วยท้อง ข้อบวม ขาเจ็บ \n รอยโรค acute serofibrinous ถึง fibrinopurulent pericarditis และ pleuritis ส่วน peritonitis พบน้อยกว่า เยื่อบุข้อบวมและคั่งเลือด น้ำในข้อเป็น serosanguineous เพิ่มขึ้น มี fibrinous adhesion เยื่อ serosa หนาและขุ่น อักเสบที่ eustachian tube และ conjunctivitis \n รักษาด้วย lincomycin และ tylosin สไลด์ระบุว่ายังไม่มีข้อมูลการป้องกันด้วยยา \n m. hyosynoviae \n ก่อข้ออักเสบเป็นหลัก แยกได้บ่อยจากสารคัดหลั่งจมูกและคอหอยของแม่สุกร \n ติดจากตัวเต็มวัยที่เป็นพาหะหรือจากสุกรเล็กช่วง 4 ถึง 8 สัปดาห์ \n pathogenesis เริ่มจากการรับเชื้อทางจมูก นำไปสู่ septicaemia แล้วลงข้อ โดยมี osteochondrosis เป็นทั้งรอยโรคที่คล้ายกันและปัจจัยโน้มนำ \n อาการ ขาเจ็บฉับพลันหนึ่งขาหรือมากกว่า เบื่ออาหารเล็กน้อยถึงปานกลาง อัตราตายต่ำ อาจเกิด suppurative arthritis แทรกซ้อน \n รอยโรค เยื่อบุข้อบวม คั่งเลือดและบวมน้ำ น้ำในข้อเป็น fibrinous ถึง serosanguineous เนื้อเยื่อรอบข้อบวมน้ำ เยื่อบุข้อหนาสีเหลืองถึงน้ำตาล \n วินิจฉัยจาก การระบาดของขาเจ็บที่ไม่ตอบสนองต่อ penicillin ร่วมกับการแยกเชื้อจากน้ำในข้อ และตรวจแอนติบอดีด้วย cft \n รักษาด้วย tylosin, lincomycin, tiamulin และ corticosteroid \n สุกรที่มี m. hyorhinis อยู่ในตัวส่วนใหญ่ไม่แสดงอาการทางคลินิก แต่เชื้อก่อโรค polyserositis, arthritis และ eustachitis ได้ในบางกรณี ตรงกับรอยโรคที่สไลด์ระบุ รวมทั้งการอักเสบที่ eustachian tube \n ในสุกร spf ที่ได้รับ m. hyorhinis ตัวเดียว ตรวจพบเชื้อที่เยื่อบุช่องลำตัว (polyserositis) แต่ไม่พบในหลอดลม ซึ่งยืนยันว่าเชื้อนี้เป็นเชื้อของ serosa และข้อเป็นหลัก มากกว่าจะเป็นเชื้อปอดโดยตรง \n m. hyosynoviae มีสถานะพาหะที่ต่อมทอนซิล และช่วงเวลาที่วิกฤตที่สุดสำหรับการแพร่เชื้อคือช่วงอนุบาล 4 ถึง 12 สัปดาห์ ซึ่งกว้างกว่าช่วง 4 ถึง 8 สัปดาห์ที่สไลด์ระบุ'],['swine-clinic--swine-pornchalit-set--gl-sser-s-disease-gl-sserella-parasuis','Glässer\'s disease (Glässerella parasuis)','glässer\'s disease (glässerella parasuis) \n แยกได้บ่อยจากสารคัดหลั่งจมูกของสุกรที่สุขภาพปกติ ความเครียดจากสิ่งแวดล้อมหรือการจัดการเป็นตัวกระตุ้นให้เกิดโรค \n ก่อ fibrinopurulent polyserositis, arthritis และ meningitis \n pathogenesis \n colonize ที่ โพรงจมูกส่วนกลางและส่วนท้าย เกิด purulent rhinitis และการสูญเสีย cilia เฉพาะที่ พร้อมเซลล์เยื่อบุจมูกและหลอดลมบวม \n การ colonize ที่ tonsil ยังเป็นข้อถกเถียง \n การบาดเจ็บของเยื่อเมือกนำไปสู่การรุกล้ำ เกิด septicemia และ endotoxin ระดับสูง ทำให้มีจุดเลือดออกที่ตับ ไต และเยื่อหุ้มสมอง พร้อม fibrinous thrombi \n เชื้อเพิ่มจำนวนที่ผิว serosa หลายแห่ง จึงได้ภาพ polyserositis, polyarthritis และ meningitis ที่เป็นลักษณะเฉพาะ \n ไม่ใช่ทุกซีโรไทป์หรือทุกสายพันธุ์ที่ก่อโรคได้ สุกรที่มีเชื้ออาจเป็นพาหะที่สุขภาพดีหรือแสดงอาการก็ได้ ขึ้นกับปัจจัยแวดล้อม \n clinical signs \n glaesserella (haemophilus) parasuis เป็นแบคทีเรียแกรมลบที่เป็น commensal เข้ามาตั้งรกรากตั้งแต่ระยะแรกในทางเดินหายใจส่วนต้นของสุกรหย่านม ตรงกับที่สไลด์ระบุว่าแยกเชื้อได้บ่อยจากสารคัดหลั่งจมูกของสุกรสุขภาพปกติ \n การติดเชื้อ g. parasuis ทำให้เกิดการติดเชื้อทั่วร่างกายพร้อม polyserositis, meningitis และ arthritis และมีอัตราป่วยกับอัตราตายสูง ตรงกับภาพรอยโรคสามอย่างที่สไลด์เรียกว่าเป็นลักษณะเฉพาะ'],['swine-clinic--swine-pornchalit-set--streptococcus-suis','Streptococcus suis','streptococcus suis \n ความสำคัญและซีโรไทป์ \n เป็นทั้งปัญหาเศรษฐกิจและปัญหาสุขภาพกับสวัสดิภาพสัตว์ และเป็น ภัยต่อสุขภาพคนเพราะมีศักยภาพ zoonotic สูง จัดเป็นโรคจากการประกอบอาชีพที่สัมผัสสุกรหรือผลิตภัณฑ์ \n ปัจจุบันจำแนกได้ 35 ซีโรไทป์ โดยซีโรไทป์ 32 และ 34 ถูกจัดใหม่เป็น streptococcus orisratti, ซีโรไทป์ 20, 22 และ 26 เสนอเป็น streptococcus parasuis และซีโรไทป์ 33 เป็น streptococcus ruminantium \n ซีโรไทป์ 2 พบมากที่สุดทั้งในสุกรและในคน รองลงมาที่พบในคนได้แก่ 4, 5, 9, 14, 16, 21, 24 และ 31 \n epidemiology \n ก่อโรคมากในลูกสุกรหลังหย่านม จนถึงอายุราว 10 สัปดาห์ ส่วนสุกรโตถือว่าค่อนข้างทนต่อโรค \n เป็น early colonizer ที่เข้ามาตั้งแต่ระหว่างคลอดหรือหลังคลอดไม่นาน แล้วกลายเป็นส่วนหนึ่งของจุลชีพประจำถิ่น ทำให้การกำจัดเชื้อออกจากฝูงทำได้ยาก \n อาศัยอยู่ใน upper respiratory tract โดยเฉพาะ tonsil และโพรงจมูก และมีความหลากหลายทางพันธุกรรมสูง \n แพร่ในแนวราบทาง oronasal route เป็นหลัก และมีการเสนอว่าแพร่ทาง aerosol ได้ด้วย \n pathogenesis \n จัดอยู่ใน porcine respiratory disease complex โดยมีโมเดลติดเชื้อร่วมกับ prrsv หรือ swine influenza virus \n ผลของการติดเชื้อร่วมมาจากการที่เชื้อตัวนำทำลาย epithelial barrier หรือเปลี่ยนการตอบสนองของภูมิคุ้มกัน การเกิด multispecies biofilm ระหว่างเชื้อ และการรบกวนสมดุลของ microbiome ในทางเดินหายใจส่วนต้น \n เชื้อที่มีแคปซูลสามารถ ทะลุเยื่อเมือกและอยู่รอดในกระแสเลือด จึงให้ภาพ septicemia, meningitis, endocarditis และ arthritis \n เข้าสู่ระบบประสาทกลางโดยผ่าน brain microvascular endothelial cell, ผ่าน blood-cerebrospinal fluid barrier และผ่านเซลล์เยื่อบุของ choroid plexus \n หน้านี้มีตารางผลการแยกเชื้อแบ่งกลุ่มเป็น systemic-confirmed และกลุ่ม non-systemic พร้อมตำแหน่งที่แยกเชื้อได้ แต่ตัวเลขจำนวนและร้อยละในไฟล์ที่สแกนมาอ่านไม่ชัดพอจะยืนยัน จึงไม่บันทึกตัวเลขไว้ \n s. suis มี 35 ซีโรไทป์ (1 ถึง 34 และ 1/2) โดยหกซีโรไทป์ถูกจัดใหม่เป็น streptococcus orisratti (32 และ 34), streptococcus parasuis (20, 22 และ 26) และ streptococcus ruminantium (33) ตรงกับตัวเลขและการจัดกลุ่มใหม่ที่สไลด์ระบุ \n s. suis เป็นสาเหตุสำคัญของการตายในลูกสุกรและสุกรรุ่นทั่วโลก โดยสายพันธุ์ที่ก่อโรคทำให้เกิด meningitis, arthritis, endocarditis, polyserositis และ septicemia ตรงกับกลุ่มอาการที่สไลด์ระบุ \n s. suis เป็นเชื้อ zoonotic ที่สร้างภาระต่อสุขภาพคนโดยเฉพาะในเอเชียตะวันออกเฉียงใต้ ในประเทศไทยพบอุบัติการณ์สะสมสูงในช่วงปี 1987 ถึง 2021 ส่วนใหญ่ในเพศชาย และการระบาดใหญ่สัมพันธ์กับการกินเนื้อหมูดิบหรืออาหารที่มีเลือดหมู โดยซีโรไทป์ 2 เป็นจีโนไทป์หลักของเชื้อจากคนไทย ตรงกับที่สไลด์ระบุว่าเป็นโรคจากการประกอบอาชีพและซีโรไทป์ 2 พบมากที่สุด \n s. suis เป็น early colonizer จึงกำจัดออกจากฝูงได้ยากแม้ใช้มาตรการจัดการอย่าง segregated early weaning ตรงกับที่สไลด์ระบุว่าเชื้อเข้ามาตั้งแต่ระหว่างคลอดหรือหลังคลอดไม่นานแล้วกลายเป็นจุลชีพประจำถิ่น']],'swine-clinic--swine-resp-viral':[['swine-clinic--swine-resp-viral--กรอบคำตอบ-ใช้โครงเดียวกับข้อทางเดินอาหาร','กรอบคำตอบ: ใช้โครงเดียวกับข้อทางเดินอาหาร','กรอบคำตอบ: ใช้โครงเดียวกับข้อทางเดินอาหาร \n ลดปริมาณเชื้อก่อโรค ได้แก่ pig flow, biosecurity, การใช้ยาต้านจุลชีพ, การใช้น้ำเชื้อจากพ่อพันธุ์ \n เพิ่มภูมิคุ้มโรค ได้แก่ วัคซีน, การจัดการโรงเรือนและอากาศ, การจัดการอาหารและน้ำ, การลดความเครียด \n prcv เป็นไวรัสกลายพันธุ์ของ tgev ที่มีการขาดหายของยีน spike ทำให้เปลี่ยน tissue tropism ไปเพิ่มจำนวนที่ทางเดินหายใจเป็นหลัก ก่อโรคอ่อนหรือไม่แสดงอาการ แต่อาจร่วมก่อกลุ่มอาการทางเดินหายใจในสุกรที่ติดเชื้อทางเดินหายใจตัวอื่นอยู่ด้วย ตรงกับการที่เอกสารจัด prcv ไว้ในกรอบ prdc'],['swine-clinic--swine-resp-viral--porcine-cytomegalovirus-inclusion-body-rhinitis','Porcine cytomegalovirus (inclusion body rhinitis)','porcine cytomegalovirus (inclusion body rhinitis) \n สาเหตุ beta-herpesvirus \n เชื้ออยู่ที่ nasal mucus gland ในโพรงจมูก ทำให้สร้างเมือกเพิ่มขึ้น และนำไปสู่การเกิด atrophic rhinitis \n ลูกสุกรจาม มีน้ำมูก แคระแกร็น และเกิด pneumonia ตามมาได้ \n รอยโรคจำเพาะคือ inclusion body rhinitis \n ป้องกันด้วย autogenous vaccine และการทำ acclimatization ในสุกรทดแทนก่อนนำเข้าฝูง \n ไม่มีแนวทางรักษาจำเพาะ ทำได้เพียงลดอาการและป้องกันโรคแทรกซ้อน เช่น ยาแก้แพ้ หรือยาต้านจุลชีพ \n pcmv เป็นเชื้อในกลุ่ม betaherpesvirus (subfamily betaherpesvirinae โดยจัดเข้า genus roseolovirus จากการวิเคราะห์จีโนมและ phylogeny) และเป็นสาเหตุของ inclusion body rhinitis ในลูกสุกรแรกเกิด \n pcmv สัมพันธ์กับ inclusion body rhinitis และ pneumonia ในลูกสุกร รวมทั้งความผิดปกติทางระบบสืบพันธุ์ในแม่สุกรอุ้มท้อง และ respiratory disease complex ในสุกรอายุมากขึ้น'],['swine-clinic--swine-resp-viral--porcine-respiratory-coronavirus-prcv','Porcine respiratory coronavirus (PRCV)','porcine respiratory coronavirus (prcv) \n สาเหตุ alpha coronavirus \n ทำให้เกิด pneumonia โดยส่วนมาก อาการไม่รุนแรง \n ป้องกันด้วย autogenous vaccine ร่วมกับการจัดการ เช่น biosecurity และ all-in-all-out ของแต่ละรุ่น \n prcv จัดอยู่ใน genus alphacoronavirus เช่นเดียวกับ tgev, pedv และ sads-cov \n prcv เป็น mutant ของ tgev ที่มีการขาดหายของ spike (s) gene ทำให้เปลี่ยน tissue tropism ไปเพิ่มจำนวนที่ทางเดินหายใจ ก่อโรคแบบไม่รุนแรงหรือไม่แสดงอาการ แต่อาจร่วมทำให้เกิดกลุ่มอาการทางระบบหายใจเมื่อมีเชื้อก่อโรคทางเดินหายใจตัวอื่นร่วมด้วย'],['swine-clinic--swine-resp-viral--swine-influenza','Swine influenza','swine influenza \n สาเหตุ influenza virus type a ชนิดที่พบมากคือ h1n1, h3n2 และ h1n2 \n เชื้อทำลาย epithelium ในทางเดินหายใจ จึงนำไปสู่ secondary infection \n ในแม่พันธุ์อาจทำให้แท้งได้ ในสุกรขุนมีอาการทางระบบหายใจและการเจริญเติบโตลดลง \n การดูแลเป็น supportive treatment \n ป้องกันด้วยวัคซีนในแม่สุกรก่อนคลอด แต่ ต้องเปลี่ยน antigen ตามการกลายพันธุ์ของไวรัส \n ติดตามด้วย serology เพื่อดูการเปลี่ยนแปลงและสัดส่วนของเชื้อในฟาร์ม \n swine influenza เกิดจาก influenza a virus โดย subtype ที่พบในสุกรได้แก่ h1n1, h1n2 และ h3n2 เชื้อเข้าสู่ร่างกายทาง aerosol แล้วแพร่อย่างรวดเร็วไปที่โพรงจมูกและ epithelium ของทางเดินหายใจส่วนหลัก \n การติดเชื้อ influenza a virus ในฝูงแม่สุกรสัมพันธ์กับสมรรถภาพการสืบพันธุ์ที่ลดลง (พบใน 79.8% ของฟาร์มที่ศึกษา) และการทำวัคซีนในแม่สุกรทำให้อัตราการแท้งและอัตราการกลับสัดลดลงอย่างมีนัยสำคัญ \n การหมุนเวียนและวิวัฒนาการของ influenza a virus ในสุกรทำให้เกิด antigenic drift อย่างมีนัยสำคัญ จนอาจเกิด antigenic mismatch ระหว่างเชื้อที่ระบาดจริงกับสายพันธุ์ในวัคซีน จึงต้องคำนึงถึงความหลากหลายของเชื้อในการเลือกสายพันธุ์วัคซีน \n การเฝ้าระวังด้วย serology ใช้ประเมินความชุกของ swine influenza a virus ในฝูง (elisa) และใช้ hemagglutination inhibition test เพื่อดูสัดส่วนของแต่ละ lineage รวมทั้งติดตามการเปลี่ยนแปลงของสัดส่วนเชื้อเมื่อมีสายพันธุ์ใหม่เกิดขึ้น']]};
